225	    // --- GET /checkout/shipping -----------------------------------------
226	    if (path === '/checkout/shipping') {
227	      if (req.method !== 'GET') { sendStatus(res, 405, 'method not allowed'); return true; }
228	      if (sess.cart.length === 0) {
229	        sendHtml(res, `<!doctype html><body><p id="error">Cart is empty. <a href="/checkout/index.html">Go back</a>.</p></body>`, 200, cookieHeader);
230	        return true;
